import xml.etree.ElementTree as ET, copy
def make_variant(remove_cables=[], merge_mass=False, remove_visuals=False):
    tree=ET.parse('/app/robot_ref.urdf')
    root=tree.getroot()
    # map link -> mass elem
    if merge_mass:
        # accumulate cable mass into parents
        # find parent of each cable joint
        parent_of={}
        for j in root.findall('joint'):
            parent_of[j.find('child').get('link')]=j.find('parent').get('link')
        added={}
        for c in remove_cables:
            # find mass
            for l in root.findall('link'):
                if l.get('name')==c:
                    m=float(l.find('inertial').find('mass').get('value'))
                    par=parent_of[c]
                    added[par]=added.get(par,0)+m
        for l in root.findall('link'):
            if l.get('name') in added:
                me=l.find('inertial').find('mass')
                me.set('value', str(float(me.get('value'))+added[l.get('name')]))
    for jname, lname in [('cable_guide_1_joint','cable_guide_1'),('cable_guide_2_joint','cable_guide_2'),('cable_guide_3_joint','cable_guide_3')]:
        if lname in remove_cables:
            for j in root.findall('joint'):
                if j.get('name')==jname:
                    root.remove(j)
            for l in root.findall('link'):
                if l.get('name')==lname:
                    root.remove(l)
    if remove_visuals:
        for link in root.findall('link'):
            for v in link.findall('visual'):
                link.remove(v)
    return tree

